    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
while True:
    # d is the period of the stable states
    d = rng.choice([4, 6, 8, 9, 10, 12])

    prime_factors = []
    if d % 2 == 0: prime_factors.append(2)
    if d % 3 == 0: prime_factors.append(3)
    if d % 5 == 0: prime_factors.append(5)

    # To create coupled cycles of stable states, we need gcd(a,d) > 1.
    # Since a = b+d, this is equivalent to gcd(b,d) > 1.
    p = rng.choice(prime_factors)
    b = p * rng.randint(2, 5) # b > 1
    a = b + d

    # Ensure N is large enough for interesting behavior
    min_N = a * 5 
    N = rng.randint(min_N // 100 + 2, min_N // 100 + 6) * 100

    # n0 should be in the 'stable' region to test the main logic.
    # n0 < N-a ensures at least one recursive step f(f(n0+a)).
    # We choose n0 < N-2a to ensure f(n0+a) is a stable value, not a transitional one.
    upper_bound = N - 2*a
    if upper_bound <= 1:
        continue # Parameters are not good, retry

    n0 = rng.randint(1, upper_bound)

    return {
        'a': a,
        'b': b,
        'N': N,
        'n0': n0,
    }

